// Generates standards/rules.yaml, the file ReviewBot reads to hold other repositories to the rules in this one.
//
// Each ADR, specification page or document that imposes something checkable carries a `rules` list in its YAML
// frontmatter, next to the rationale the rule comes from. This script collects those lists from
//   docs/adr/*.md, docs/*.md and spec/*.md
// into one generated file. Nobody edits standards/rules.yaml by hand: CI runs `--check`, which fails when the
// committed file differs from what the documents say.
//
// Usage:
//   node scripts/generate-standards.mjs          write standards/rules.yaml
//   node scripts/generate-standards.mjs --check  fail if standards/rules.yaml is out of date
//
// The format and its limits are described in AGENTS.md ("Standards rules"). The rules schema is the one ReviewBot
// enforces, vendored in scripts/standards/ (see rules-schema.mjs).

import { createHash } from "node:crypto";
import { existsSync, readFileSync, readdirSync, writeFileSync, mkdirSync } from "node:fs";
import { dirname, join, relative, resolve, sep } from "node:path";
import { fileURLToPath } from "node:url";
import yaml from "js-yaml";
import { STANDARDS_RULES_SCHEMA_VERSION, checkRule, checkRulesFile } from "./standards/rules-schema.mjs";

const defaultRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const SOURCE_DIRS = ["docs/adr", "docs", "spec"];
/** A document with one of these statuses contributes no rules. */
const INACTIVE_STATUSES = new Set(["superseded", "deprecated"]);
export const OUTPUT_PATH = "standards/rules.yaml";

const HEADER = `# Generated by scripts/generate-standards.mjs from the \`rules\` in the frontmatter of the documents named in
# each rule's \`source\`. Do not edit by hand: edit the document and run \`node scripts/generate-standards.mjs\`.
# ReviewBot reads this file; CI fails when it is out of date.
`;

/** The YAML frontmatter of a Markdown document, or null when it has none. Throws on invalid YAML. */
export function parseFrontmatter(text) {
  const match = /^---\r?\n([\s\S]*?)\r?\n---\r?\n/.exec(text);
  if (!match) return null;
  const data = yaml.load(match[1]);
  return data && typeof data === "object" && !Array.isArray(data) ? data : null;
}

/**
 * Whether a document no longer applies. The status is the status key of the frontmatter when there is one,
 * otherwise the ADR's own body line ("- **Status:** Superseded by ADR 0012"), where this repository keeps it. Only
 * the first word counts, so "Superseded by ..." and "Deprecated" both switch the rules off.
 */
export function isInactive(front, text) {
  let status = front?.status;
  if (status === undefined) {
    const body = /^- \*\*Status:\*\*\s*(.+)$/im.exec(text);
    status = body ? body[1] : "";
  }
  const first = String(status).trim().toLowerCase().split(/[\s,;:.]+/)[0];
  return INACTIVE_STATUSES.has(first);
}

/** Natural order for rule ids, so ADR-0009-R2 sorts before ADR-0009-R10. */
export function compareRuleIds(a, b) {
  const pa = a.split(/(\d+)/);
  const pb = b.split(/(\d+)/);
  for (let i = 0; i < Math.min(pa.length, pb.length); i += 1) {
    if (pa[i] === pb[i]) continue;
    if (/^\d+$/.test(pa[i]) && /^\d+$/.test(pb[i])) {
      const diff = Number(pa[i]) - Number(pb[i]);
      if (diff !== 0) return diff;
      continue;
    }
    return pa[i] < pb[i] ? -1 : 1;
  }
  return pa.length - pb.length || (a < b ? -1 : a > b ? 1 : 0);
}

function markdownFiles(root) {
  const files = new Set();
  const walk = (dir) => {
    for (const entry of readdirSync(dir, { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name))) {
      const full = join(dir, entry.name);
      if (entry.isDirectory()) walk(full);
      else if (entry.name.endsWith(".md")) files.add(full);
    }
  };
  // Subfolders are scanned too (docs/prd, docs/erd, spec/conformance); a file reachable from two roots counts once.
  for (const dir of SOURCE_DIRS) {
    const full = join(root, dir);
    if (existsSync(full)) walk(full);
  }
  return [...files].sort();
}

/**
 * Collects every active rule from the documents under `root`. Returns the rules, sorted, with the `source`
 * of each, and a list of problems (empty when everything is valid).
 */
export function collectRules(root = defaultRoot) {
  const rules = [];
  const problems = [];
  const seen = new Map();

  for (const file of markdownFiles(root)) {
    const path = relative(root, file).split(sep).join("/");
    let front;
    let text;
    try {
      text = readFileSync(file, "utf8");
      front = parseFrontmatter(text);
    } catch (error) {
      problems.push(`${path}: the frontmatter is not valid YAML (${error.message})`);
      continue;
    }
    if (!front || front.rules === undefined) continue;

    if (typeof front.id !== "string" || front.id.length === 0) {
      problems.push(`${path}: a document with rules needs an \`id\` in its frontmatter, for example ADR-0009`);
      continue;
    }
    if (isInactive(front, text)) continue;
    if (!Array.isArray(front.rules)) {
      problems.push(`${path}: rules must be a list`);
      continue;
    }

    for (const [index, raw] of front.rules.entries()) {
      const where = `${path} rules[${index}]${raw?.id ? ` (${raw.id})` : ""}`;
      const rule = { id: raw?.id, severity: raw?.severity, appliesTo: raw?.appliesTo, text: raw?.text, source: path };
      const found = checkRule(rule, where);
      if (found.length > 0) {
        problems.push(...found);
        continue;
      }
      if (!rule.id.startsWith(`${front.id}-R`)) {
        problems.push(`${where}: the id must start with the document id (${front.id}-R<n>)`);
        continue;
      }
      if (seen.has(rule.id)) {
        problems.push(`${where}: duplicate rule id, also used in ${seen.get(rule.id)}`);
        continue;
      }
      seen.set(rule.id, path);
      rules.push({
        id: rule.id,
        severity: rule.severity,
        appliesTo: [...rule.appliesTo],
        text: rule.text.trim().replace(/\s+/g, " "),
        source: path,
      });
    }
  }

  rules.sort((a, b) => compareRuleIds(a.id, b.id));
  return { rules, problems };
}

/** The text of standards/rules.yaml for a list of rules. Deterministic: the same rules give the same text. */
export function renderRulesFile(rules) {
  const hash = createHash("sha256").update(JSON.stringify(rules)).digest("hex").slice(0, 12);
  const file = { version: STANDARDS_RULES_SCHEMA_VERSION, generatedFrom: `sha256:${hash}`, rules };
  const problems = checkRulesFile(file);
  if (problems.length > 0) throw new Error(`the generated file is invalid: ${problems.join("; ")}`);
  return HEADER + yaml.dump(file, { lineWidth: -1, noRefs: true });
}

/** Generates the file. With `check`, compares instead of writing. Returns { ok, message }. */
export function run({ root = defaultRoot, check = false } = {}) {
  const { rules, problems } = collectRules(root);
  if (problems.length > 0) return { ok: false, message: `rules are invalid:\n- ${problems.join("\n- ")}` };

  const text = renderRulesFile(rules);
  const target = join(root, OUTPUT_PATH);
  if (check) {
    const current = existsSync(target) ? readFileSync(target, "utf8") : null;
    if (current !== text) {
      return {
        ok: false,
        message: `${OUTPUT_PATH} is out of date. Run \`node scripts/generate-standards.mjs\` and commit the result.`,
      };
    }
    return { ok: true, message: `${OUTPUT_PATH} is up to date (${rules.length} rules)` };
  }
  mkdirSync(dirname(target), { recursive: true });
  writeFileSync(target, text);
  return { ok: true, message: `wrote ${OUTPUT_PATH} (${rules.length} rules)` };
}

if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const result = run({ check: process.argv.includes("--check") });
  (result.ok ? console.log : console.error)(result.message);
  process.exit(result.ok ? 0 : 1);
}
